function billLines(input: {
  yard: YardInfo;
  kind: BillKind;
  billNo: string;
  date: string;
  company: string;
  serials: string[];
  quantity: number;
  price: number | null;
  total: number | null;
  payment: PaymentStatus;
  paid: number | null;
  note: string;
  cylinderType?: string;
}): string[] {
  return [
    input.yard.name,
    input.yard.address,
    [input.yard.phone, input.yard.gst && `GST ${input.yard.gst}`, input.yard.pan && `PAN ${input.yard.pan}`].filter(Boolean).join("  "),
    "",
    input.kind === "sale" ? "SALE BILL" : "PURCHASE BILL",
    `Bill ${input.billNo}`,
    `Date ${input.date}`,
    `Company ${input.company}`,
    "",
    "Serials",
    ...(input.serials.length ? input.serials : ["—"]),
    "",
    `Cylinders ${input.quantity}${input.cylinderType ? ` × ${input.cylinderType}` : ""}`,
    `Price ${rupee(input.price)}`,
    `Amount ${rupee(input.total)}`,
    `Payment ${paymentLabel(input.payment)}`,
    `Received ${rupee(input.paid)}`,
    input.note,
    "",
    "Cxyledge",
  ].filter((line) => line != null);
}

